(()=>{'use strict';const C=window.CareV2,el=(t,s,cl)=>{const x=document.createElement(t);if(s!==undefined)x.textContent=s;if(cl)x.className=cl;return x;};
const drawings=[
'<circle cx="26" cy="28" r="8"/><circle cx="48" cy="19" r="7"/><circle cx="66" cy="33" r="9"/><circle cx="44" cy="40" r="6"/>',
'<path d="M14 34 Q12 19 26 23 Q30 10 41 19 Q48 11 57 19 Q75 12 80 26 Q88 40 73 42 Q67 50 56 42 Q43 50 36 42 Q21 48 14 34Z"/>',
'<path d="M15 33 Q17 16 38 19 L71 17 Q86 19 81 34 Q77 42 62 38 L29 42 Q14 45 15 33Z"/><path d="M32 22 l5 7 -6 8 M54 21 l-4 8 5 8 M70 21 l-5 7 5 7" fill="none" stroke="#fff5df" stroke-width="2"/>',
'<path d="M13 32 Q15 16 38 20 Q59 24 70 17 Q85 12 84 27 Q84 41 63 40 Q42 37 30 43 Q12 48 13 32Z"/>',
'<ellipse cx="26" cy="27" rx="13" ry="9"/><ellipse cx="62" cy="20" rx="14" ry="8"/><ellipse cx="56" cy="40" rx="17" ry="9"/>',
'<path d="M14 24 l12 -9 10 6 11 -9 11 10 14 -4 3 9 11 4 -10 7 -4 12 -13 -6 -8 9 -11 -8 -17 2 1 -10 -13 -5Z"/>',
'<path d="M12 33 Q25 23 38 31 T67 31 Q85 22 86 34 Q82 47 53 44 Q20 48 12 33Z"/><path d="M27 8 q-10 14 0 14 q10 0 0 -14 M65 7 q-10 14 0 14 q10 0 0 -14"/>'
];
function stool(index){const s=document.createElementNS('http://www.w3.org/2000/svg','svg');s.setAttribute('viewBox','0 0 100 56');s.setAttribute('aria-hidden','true');s.setAttribute('class','cv-stool');s.setAttribute('fill','#91704d');s.innerHTML=drawings[index];return s;}
function create(root,{paged=false,onChange=()=>{}}={}){root.replaceChildren();let a={};const refs={},pages=[];C.groups.forEach((title,g)=>{const page=el(paged?'section':'details',undefined,'cv-page');page.dataset.group=g;if(!paged)page.open=g===0;const head=el(paged?'h2':'summary',String(g+1).padStart(2,'0')+' · '+title,'cv-heading');head.tabIndex=-1;page.append(head);pages.push(page);root.append(page);let measureBox;
for(const f of C.fields.filter(f=>f.group===g)){let target=page;if(f.type==='measure'){if(!measureBox){measureBox=el('details',undefined,'cv-measures');measureBox.append(el('summary','这一天有测量，再补充'),el('p','只填已测数值。没测就留空，不等于正常。','cv-hint'));page.append(measureBox)}target=measureBox;}
const box=el('fieldset',undefined,'cv-question');box.dataset.field=f.id;const legend=el('legend',f.label+(f.type==='multi'?' · 可多选':''));box.append(legend);if(f.hint)box.append(el('p',f.hint,'cv-hint'));const inputs=[];
if(f.type==='measure'){const l=el('label',undefined,'cv-number');const i=el('input');Object.assign(i,{type:'number',name:'v2-'+f.id,id:'v2-'+f.id,min:String(f.min),max:String(f.max),step:String(f.step),inputMode:f.step===1?'numeric':'decimal',placeholder:'未测请留空'});i.setAttribute('aria-label',f.label);l.append(i,el('span',f.unit));box.append(l);inputs.push(i);i.addEventListener('input',()=>{if(i.value==='')delete a[f.id];else a[f.id]=Number(i.value);changed()});}
else if(f.type==='text'){const i=el('textarea');Object.assign(i,{id:'v2-'+f.id,name:'v2-'+f.id,rows:3,maxLength:f.maxLength,placeholder:f.placeholder});i.setAttribute('aria-label',f.label);box.append(i);inputs.push(i);i.addEventListener('input',()=>{if(i.value.trim())a[f.id]=i.value;else delete a[f.id];changed()});}
else if(f.type==='count'){const s=el('select');s.name='v2-'+f.id;s.id='v2-'+f.id;s.setAttribute('aria-label',f.label);const vals=f.choiceCounts?[['','请选择（可跳过）'],...f.choiceCounts.map(v=>[String(v),typeof v==='number'?v+' 次':v])]:[['','请选择（可跳过）'],...Array.from({length:31-f.min},(_,j)=>[String(j+f.min),String(j+f.min)+' 次']),['30 次以上','30 次以上'],['不清楚','不清楚／记不清']];for(const[v,t]of vals){const o=el('option',t);o.value=v;s.append(o)}box.append(s);inputs.push(s);s.addEventListener('change',()=>{if(s.value==='')delete a[f.id];else a[f.id]=/^\d+$/.test(s.value)?Number(s.value):s.value;changed()});}
else{const choices=el('div',undefined,'cv-choices'+(f.wide?' cv-wide':'')+(f.illustrated?' cv-illustrated':''));for(const [j,v]of f.options.entries()){const l=el('label',undefined,'cv-choice'),i=el('input');i.type=f.type==='multi'?'checkbox':'radio';i.name='v2-'+f.id;i.value=v;const face=el('span',undefined,'cv-face');if(f.illustrated&&j<7)face.append(stool(j));face.append(el('span',v==='不清楚'?'不清楚／没问到':v));l.append(i,face);choices.append(l);inputs.push(i);i.addEventListener('change',()=>{if(f.type==='multi'){let vls=Array.isArray(a[f.id])?[...a[f.id]]:[];const exclusive=[f.none,'不清楚',...(f.exclusive||[])].filter(Boolean);if(i.checked){if(exclusive.includes(v))vls=[v];else vls=[...vls.filter(x=>!exclusive.includes(x)&&x!==v),v]}else vls=vls.filter(x=>x!==v);if(vls.length)a[f.id]=f.options.filter(x=>vls.includes(x));else delete a[f.id];}else a[f.id]=v;changed()});}box.append(choices);}
const clear=el('button','清除此项','cv-clear');clear.type='button';clear.setAttribute('aria-label','清除'+f.label);clear.onclick=()=>{delete a[f.id];changed()};box.append(clear);target.append(box);refs[f.id]={box,inputs,clear};}
});
function sync(force=false){a=C.clean(a);for(const f of C.fields){const r=refs[f.id],v=a[f.id];r.box.hidden=!C.active(f,a);r.clear.hidden=!C.present(v);for(const i of r.inputs){if(i.type==='radio'||i.type==='checkbox')i.checked=Array.isArray(v)?v.includes(i.value):v===i.value;else if(force||document.activeElement!==i||(i.type!=='number'&&i.tagName!=='TEXTAREA'))i.value=C.present(v)?String(v):'';}}}
function changed(){sync();onChange(C.clean(a));}
sync();return {get:()=>C.clean(a),set:v=>{a=JSON.parse(JSON.stringify(v||{}));sync(true);},show:g=>{if(paged)pages.forEach((p,i)=>p.hidden=i!==g);},focus:g=>pages[g].querySelector('.cv-heading').focus({preventScroll:true}),pages,refs};}
window.CareControls={create};})();
